package main

import "strconv"

// All agent connection routes share this presentation. Host adapters describe
// existing controls; connection and permission authority remain with their owners.
func agentConnectionPage(agent, host, scope string, nativeReadback bool) string {
	return pageOwnsReady(oaPageHead("status", agent, "Connect "+agent+" to OpenAbstractions.")) +
		oaGroup("agent-connection", "Connection", "", oaRow("State", "", `<button id="agent-primary" class="oa-primary" disabled>Connect</button><button id="agent-refresh">Check again</button>`, "agent-status"), `<p id="agent-guidance" class="oa-status"></p>`) +
		oaGroup("agent-receiving", "Receiving messages", "", oaRow("Receive messages while "+agent+" is idle", "", `<span id="agent-receive-control" hidden><input id="agent-receive" type="checkbox" class="switch" aria-label="Receive messages while `+agent+` is idle" disabled></span>`, "agent-receive-status"), `<p id="agent-receiving-guidance" class="oa-status"></p>`) +
		oaGroup("agent-answering", "Answering for you", "Person-only permissions stay with you.",
			oaRow("Questions an assistant may answer", "", "", "agent-assistant-status"),
			`<div id="agent-observe-row" hidden>`+oaRow("Answer questions while idle", "", `<span id="agent-observe-control" hidden><input id="agent-observe" type="checkbox" class="switch" aria-label="Answer questions while idle" disabled></span>`, "agent-observe-status")+`</div>`, `<p id="agent-answering-guidance" class="oa-status"></p>`) +
		oaExpander("Details", `<div id="agent-details">`+oaRow("Applies to", scope, "", "")+`<p>Connected confirms saved setup. Live message reception is not observed by this page.</p><div id="agent-saved"></div>`+
			`<div id="agent-project-row" hidden>`+oaRow("Project", "", `<button id="agent-project">Choose project…</button>`, "agent-project-status")+`</div>`+
			`<button id="agent-open" data-status="agent-status" hidden>Open `+agent+`</button><button id="agent-reset" data-status="agent-status" hidden>Reset receiving setup</button>`+oaTechnicalDetails(`<pre id="agent-technical"></pre>`)+`</div>`) +
		`<script>` + serviceCommonScript + `const agentHost=` + strconv.Quote(host) + `,agentName=` + strconv.Quote(agent) + `,agentNativeReadback=` + strconv.FormatBool(nativeReadback) + `;` + agentConnectionScript + `</script>`
}

const agentConnectionScript = `
let agentClosed=false,agentRunId=0,agentRun=null,agentView=null,agentSelection='',agentAction='connect',agentRow=null;
const agentReopen={connection:false,receiving:false,answering:false};
const agentPath='/connections/'+agentHost;
// An approved update waits only for its running apps; the batch publishes them together.
function agentRestartSentence(hosts){const names=(hosts&&hosts.length?hosts:[agentName]).slice();const last=names.pop();return 'Restart '+(names.length?names.join(', ')+' and ':'')+last+' to finish updating.'}
function agentEnabled(state){return state==='owned'||state==='preexisting'}
function agentRowRequest(row){return {revision:agentView.revision,project_key:row.project_key,program_key:row.program_key,name:row.name,kind:row.kind||''}}
function agentDisable(){for(const id of ['primary','receive','observe','project','reset','open'])el('agent-'+id).disabled=true;for(const control of el('agent-saved').querySelectorAll('button'))control.disabled=true}
// agentSections shows Receiving messages and Answering for you only when
// the connection's state was read and its setup is available; otherwise
// the Connection guidance says why once (owner, 2026-09-23: "no empty
// fields"; R19b render check, 2026-11-09).
function agentSections(shown){el('agent-receiving').hidden=!shown;el('agent-answering').hidden=!shown}
function agentSwitch(id,enabled,available,reason){const control=el('agent-'+id);control.checked=enabled;control.disabled=!available;el('agent-'+id+'-control').hidden=!available;el('agent-'+id+'-status').textContent=reason}
function drawAgent(view){
 agentView=view;el('agent-technical').textContent=JSON.stringify(view,null,2);
 const claude=agentHost==='claude',nativeSaved=agentNativeReadback&&view.helper_enrollment==='enrolled',rows=claude?(view.connections||[]):view.owned||nativeSaved?[view]:[],saved=rows.filter(row=>row.registration==='saved'||agentNativeReadback&&row.helper_enrollment==='enrolled');
 agentRow=saved.find(row=>row.helper_state==='update')||saved.find(row=>row.kind==='user')||saved[0]||null;
 const update=saved.some(row=>row.helper_state==='update'||agentNativeReadback&&row.helper_state==='update_available'),changed=view.registration==='changed'||rows.some(row=>row.registration==='changed')||agentNativeReadback&&(view.host_registration==='conflict'||nativeSaved&&!['current','update','update_available','restart'].includes(view.helper_state)),backgroundDisabled=(view.background||{}).state==='disabled',modPending=claude&&saved.some(row=>row.kind==='user'&&row.mod_state!=='current'&&!backgroundDisabled),restartRow=saved.find(row=>row.helper_state==='restart'),restart=!!restartRow,current=saved.length>0&&saved.every(row=>row.helper_state==='current'&&(!claude||row.kind!=='user'||row.mod_state==='current'||backgroundDisabled))&&(!agentNativeReadback||view.owned===true);
 const available=view.supported!==false&&view.outcome==='page',replace=agentNativeReadback&&view.host_registration==='conflict';
 agentAction=replace||claude&&view.reconnect_available?'connect':update?'update':restart?(agentNativeReadback?'none':'disconnect'):agentNativeReadback?'connect':modPending?'connect':saved.length?'disconnect':'connect';
 el('agent-status').textContent=!available||changed?'Needs attention':restart?'Restart needed':update?'Update ready':saved.length&&current?'Connected':saved.length?'Needs attention':'Not connected';
 el('agent-guidance').textContent=!available?'Connection setup is unavailable.':replace?agentName+"'s saved entry changed. Connect replaces it.":changed?'Saved setup changed; review Details.':restart?agentRestartSentence(restartRow.restart_hosts):claude&&!view.cli_available?(view.reconnect_available?'Claude Code changed since you connected it. Connect again to use it.':view.cli_reason_code==='cli_saved_verification'?view.cli_reason:'Open a local Code session, then check again.'):update?(saved.find(row=>row.helper_state==='update'&&row.update_failure)?'Update stopped: '+saved.find(row=>row.helper_state==='update'&&row.update_failure).update_failure+'.':'Review the updated connection.'):agentReopen.connection?'Reopen '+agentName+' after changes.':saved.length?'':'Connect and review the OpenAbstractions request.';
 el('agent-primary').textContent=agentNativeReadback&&current?'Connected':agentAction==='update'?'Update':agentAction==='disconnect'?'Disconnect':'Connect';
 el('agent-primary').disabled=!available||changed&&!replace||agentNativeReadback&&current||(claude?(agentAction==='connect'&&(!view.registration_available||!(view.cli_available||view.reconnect_available)||view.project_required&&!agentSelection)):(agentAction==='connect'&&!view.available));
 el('agent-primary').hidden=agentNativeReadback&&current||agentAction==='none';
 agentSections(available);
 const reason=saved.length?'Reading and replying keep their own permissions.':'Connect to enable this option.';
 agentSwitch('receive',claude&&agentEnabled((view.background||{}).state),claude&&!!view.background_available&&(!!saved.length||agentEnabled((view.background||{}).state)),claude?reason:'Idle receiving cannot be changed here.');
 el('agent-assistant-status').textContent='Answering permission is requested inside '+agentName+'.';
 agentSwitch('observe',claude&&agentEnabled((view.background_asks||{}).state),claude&&!!view.background_available&&!!saved.length,'Each answering permission is reviewed separately.');
 el('agent-observe-row').hidden=el('agent-observe-control').hidden;
 el('agent-receiving-guidance').textContent=agentReopen.receiving?'Reopen '+agentName+' after changes.':'';
 el('agent-answering-guidance').textContent=agentReopen.answering?'Reopen '+agentName+' after changes.':'';
 el('agent-project-row').hidden=!claude||!view.project_required;el('agent-project').disabled=!view.picker_available;
 el('agent-open').hidden=!claude||!view.open_available||view.cli_available;el('agent-open').disabled=!view.open_available;
 el('agent-reset').hidden=!claude||!view.background_available;el('agent-reset').disabled=!view.background_available;
 const list=el('agent-saved');list.replaceChildren();
 for(const row of rows){const item=document.createElement('div');item.className='oa-row';const text=document.createElement('span');text.className='oa-row-label';text.textContent=claude?(row.kind==='user'?'All projects':row.kind==='plugin'?'Project plugin':'Earlier project connection'):'Saved account connection';item.append(text);if(claude&&row.registration==='saved'){const remove=document.createElement('button');remove.textContent='Disconnect';remove.onclick=()=>agentChange('disconnect',row);item.append(remove)}else{const state=document.createElement('span');state.textContent=claude&&row.registration!=='saved'?'Changed':'Saved';item.append(state)}list.append(item)}
 if(!rows.length)para(list,'No saved connection.');
}
async function refreshAgent(){if(agentClosed)return;const runId=++agentRunId;if(agentRun)agentRun.abort();const run=new AbortController();agentRun=run;agentDisable();try{const view=await call(agentPath+'/state',undefined,run.signal);if(agentClosed||run.signal.aborted||runId!==agentRunId)return;drawAgent(view)}catch(error){if(!agentClosed&&!run.signal.aborted&&runId===agentRunId){agentDisable();agentSections(false);el('agent-status').textContent='Needs attention';const unread=()=>{el('agent-guidance').textContent='The connection could not be read. Check again.'};if(typeof oaRuntimeEcho==='function')oaRuntimeEcho('agent-guidance',unread,error&&error.message);else unread();fail('agent-technical',error)}}}
function agentReceivingFailure(action,confirmed,error){drawAgent(confirmed);const observe=action==='background-asks',id=observe?'observe':'receive';el('agent-'+id+'-status').textContent='Last confirmed: '+(el('agent-'+id).checked?'On.':'Off.');el(observe?'agent-answering-guidance':'agent-receiving-guidance').textContent='The change could not be confirmed. Check again.';fail('agent-technical',error)}
async function agentChange(action,row){if(agentClosed||!agentView)return;const confirmed=agentView;const runId=++agentRunId;if(agentRun)agentRun.abort();const run=new AbortController();agentRun=run;agentDisable();el('agent-status').textContent='Review the OpenAbstractions request.';try{const claude=agentHost==='claude';let route=action,body={revision:agentView.revision};if(action==='connect'){route=claude||agentNativeReadback?'connect':'add';if(claude)body={selection:agentSelection}}else if(action==='disconnect'){route=claude?'disconnect':'remove';if(claude)body=agentRowRequest(row||agentRow)}else if(action==='update'&&claude)body=agentRowRequest(row||agentRow);else if(action==='update'&&agentNativeReadback)route='connect';else if(action==='background'||action==='background-asks')body.action=action==='background'?(el('agent-receive').checked?'enable':'disable'):(el('agent-observe').checked?'enable':'disable');else if(action==='reset'){route='background';body.action='reset'}
 const reply=await call(agentPath+'/'+route,body,run.signal);if(agentClosed||run.signal.aborted||runId!==agentRunId)return;if(['page','saved','removed','updated','cleanup_pending'].includes(reply.outcome)){const section=action==='background'||action==='reset'?'receiving':action==='background-asks'?'answering':'connection';agentReopen[section]=true}if(agentNativeReadback){drawAgent(reply);agentOutcome(reply,action)}else{const refreshed=agentRunId+1;await refreshAgent();if(agentClosed||agentRunId!==refreshed)return;agentOutcome(reply,action)}
 }catch(error){if(!agentClosed&&!run.signal.aborted&&runId===agentRunId){if(['background','background-asks','reset'].includes(action)){agentReceivingFailure(action,confirmed,error);return}const refreshed=agentRunId+1;await refreshAgent();if(agentClosed||agentRunId!==refreshed)return;el('agent-status').textContent='Needs attention';el('agent-guidance').textContent=action==='update'?agentUpdateFailure(error):'The change could not be confirmed. Check again.';fail('agent-technical',error)}}}
// The Update button always ends with one sentence for its outcome.
function agentUpdateSentence(reply){const outcome=reply.outcome;if(outcome==='updated'||agentNativeReadback&&outcome==='page'&&reply.helper_state==='current')return 'Updated. Restart '+agentName+' to use the new connector.';if(outcome==='update_pending'||reply.restart_required)return 'Update waits until '+agentName+' is closed.';if(outcome==='current')return agentName+' already has the current connector.';if(outcome==='not_now')return 'Update postponed; the current connector stays in use.';return ''}
function agentUpdateFailure(error){const text=String(error&&error.message||error||'');if(/requires restart|update_pending/i.test(text))return 'Update waits until '+agentName+' is closed.';const reason=/in progress/i.test(text)?'another change is in progress':/changed/i.test(text)?'the connection changed, check again':/refused|stopped/i.test(text)?'OpenAbstractions stopped the change':/timeout|deadline/i.test(text)?'it took too long':/unavailable/i.test(text)?'the connection is unavailable':'see Details';return 'Update failed: '+reason+'.'}
function agentOutcome(reply,action){const sentence=action==='update'?agentUpdateSentence(reply):'';if(sentence){el('agent-guidance').textContent=sentence;if(reply.outcome==='update_pending'||reply.restart_required)el('agent-technical').textContent=JSON.stringify({operation:reply,connection:agentView},null,2);return}agentNotice(reply,action)}
function agentNotice(reply,action){const notice=({connect_pending:'Review the pending OpenAbstractions request, then check again.',conflict:'Saved setup changed; check again before connecting.',permission_pending:'Review the pending OpenAbstractions request, then check again.',permission_error:'Permission review failed. Check again before connecting.',cleanup_pending:'Connection saved. Earlier permissions need cleanup; see Details.',declined:'Your permissions were not changed.',unavailable:'The change is unavailable. Check again.',unknown:'The change outcome is unknown. Check again.'})[reply.outcome];if(notice){if(reply.outcome!=='declined')el('agent-status').textContent='Needs attention';el('agent-guidance').textContent=notice;el('agent-technical').textContent=JSON.stringify({operation:reply,connection:agentView},null,2)}else if(reply.companion==='unavailable'){el('agent-status').textContent='Needs attention';el('agent-guidance').textContent='Receiving setup is incomplete. Connect again to finish.'}else if(action==='update'){el('agent-guidance').textContent='Update result unknown; check again.'}}
el('agent-primary').onclick=()=>agentChange(agentAction);el('agent-refresh').onclick=refreshAgent;
el('agent-receive').onchange=()=>agentChange('background');el('agent-observe').onchange=()=>agentChange('background-asks');el('agent-reset').onclick=()=>agentChange('reset');
el('agent-open').onclick=()=>agentChange('open');
el('agent-project').onclick=async()=>{if(agentClosed)return;const runId=++agentRunId;if(agentRun)agentRun.abort();const run=new AbortController();agentRun=run;agentSelection='';agentDisable();try{const picked=await call(agentPath+'/project',{},run.signal);if(agentClosed||run.signal.aborted||runId!==agentRunId)return;agentSelection=picked.outcome==='selected'?picked.selection:'';el('agent-project-status').textContent=agentSelection?'Project selected.':'No project selected.';await refreshAgent()}catch(error){if(!agentClosed&&!run.signal.aborted&&runId===agentRunId)fail('agent-project-status',error)}};
addEventListener('pagehide',()=>{agentClosed=true;agentRunId++;if(agentRun)agentRun.abort();agentDisable();if(!agentNativeReadback)fetch(agentPath+'/cancel',{method:'POST',headers:{'X-Panel-Key':key},keepalive:true}).catch(()=>{})},{once:true});
refreshAgent().finally(()=>{if(!agentClosed)oaReady()});
if(typeof oaOnRuntimeBack==='function')oaOnRuntimeBack(refreshAgent);
`
